#!/usr/bin/env python3
"""Regenerate src/art/cjk.rs: 12x12 bitmaps of every non-ASCII character used
in string literals under src/, taken from the Ark Pixel Font 12px
(monospaced, zh_hans) BDF file.

Usage: python3 tools/gen_cjk.py path/to/ark-pixel-12px-monospaced-zh_hans.bdf

The font is available from https://github.com/TakWolf/ark-pixel-font
(SIL Open Font License 1.1, see LICENSE-ARK-PIXEL-FONT.txt).
"""

import pathlib
import re
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
OUT = ROOT / "src" / "art" / "cjk.rs"
SIZE = 12
BASELINE = 10  # rows above the baseline in the 12px cell (ascent)


def used_chars():
    chars = set()
    for path in (ROOT / "src").rglob("*.rs"):
        if path == OUT:
            continue
        for lit in re.findall(r'"((?:[^"\\]|\\.)*)"', path.read_text(encoding="utf-8")):
            chars.update(c for c in lit if ord(c) > 0x7F)
    return sorted(chars)


def read_bdf(path):
    glyphs = {}
    lines = iter(pathlib.Path(path).read_text(encoding="utf-8").splitlines())
    for line in lines:
        if not line.startswith("STARTCHAR"):
            continue
        enc = bbx = None
        for line in lines:
            if line.startswith("ENCODING"):
                enc = int(line.split()[1])
            elif line.startswith("BBX"):
                bbx = tuple(int(v) for v in line.split()[1:5])
            elif line == "BITMAP":
                w, h, xoff, yoff = bbx
                rows = [int(next(lines), 16) for _ in range(h)]
                width_bits = (w + 7) // 8 * 8
                cell = [0] * SIZE
                top = BASELINE - (h + yoff)
                for r, bits in enumerate(rows):
                    y = top + r
                    for x in range(w):
                        if bits >> (width_bits - 1 - x) & 1 and 0 <= y < SIZE and 0 <= xoff + x < SIZE:
                            cell[y] |= 1 << (SIZE - 1 - (xoff + x))
                glyphs[enc] = cell
                break
    return glyphs


def main():
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    glyphs = read_bdf(sys.argv[1])
    chars = used_chars()
    missing = [c for c in chars if ord(c) not in glyphs]
    if missing:
        sys.exit("no glyph for: " + "".join(missing))
    out = [
        "//! 12x12 bitmaps for the non-ASCII characters the game uses, generated by",
        "//! `tools/gen_cjk.py` from Ark Pixel Font 12px (Copyright (c) 2021,",
        "//! TakWolf; SIL Open Font License 1.1, see LICENSE-ARK-PIXEL-FONT.txt).",
        "//! Do not edit by hand; rerun the tool after changing text.",
        "",
        "/// Rows top to bottom; bit 11 is the leftmost pixel. Sorted by character.",
        "#[rustfmt::skip]",
        "pub const GLYPHS: &[(char, [u16; 12])] = &[",
    ]
    for c in chars:
        rows = ", ".join(f"0x{r:03x}" for r in glyphs[ord(c)])
        out.append(f"    ('{c}', [{rows}]),")
    out.append("];")
    OUT.write_text("\n".join(out) + "\n", encoding="utf-8")
    print(f"wrote {len(chars)} glyphs to {OUT.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
